-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0003_stores_submit.up.sql
-- ─────────────────────────────────────────────────────────────────────────

-- ============================================================================
-- 0003_stores_submit (UP) — community submit write path.
--   • own-submission read policy (submitter sees their pending; public does not)
--   • submit_store() RPC: server-side validation + spatial dedupe, then inserts a
--     pending/community row owned by auth.uid(). This is the ONLY write path —
--     there is deliberately no INSERT policy, so every write is validated here.
-- Reversible: see 0003_stores_submit.down.sql.
-- ============================================================================

-- 1) Submitter can read their OWN rows (any status), in addition to the public
--    "approved-only" policy from 0001. RLS policies are OR'd, so anon still sees
--    only approved; a pending row is visible to its submitter alone.
drop policy if exists "read own submissions" on public.stores;
create policy "read own submissions" on public.stores
  for select to authenticated
  using (submitted_by = auth.uid());

-- 2) The validated, deduped write path.
create or replace function public.submit_store(
  in_name        text,
  in_category    text,
  in_halal_scope text,
  in_address     text,
  in_city        text,
  in_state       text,
  in_zip         text,
  in_lat         double precision,
  in_lng         double precision
)
returns uuid
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid   uuid := auth.uid();
  v_point geography := st_setsrid(st_makepoint(in_lng, in_lat), 4326)::geography;
  v_dup   uuid;
  v_id    uuid;
begin
  -- auth gate
  if v_uid is null then
    raise exception 'auth required' using errcode = '28000';
  end if;

  -- server-side validation (mirrors the client checks; never trusts the client)
  if in_name is null or length(btrim(in_name)) < 2 then
    raise exception 'invalid name' using errcode = '22023';
  end if;
  if in_lat is null or in_lng is null
     or in_lat < -90 or in_lat > 90 or in_lng < -180 or in_lng > 180
     or (abs(in_lat) < 0.0001 and abs(in_lng) < 0.0001) then
    raise exception 'invalid coordinates' using errcode = '22023';
  end if;
  if in_category is null
     or not exists (select 1 from unnest(enum_range(null::store_category)) e
                    where e::text = in_category) then
    raise exception 'invalid category' using errcode = '22023';
  end if;
  if in_halal_scope is null
     or not exists (select 1 from unnest(enum_range(null::halal_scope)) e
                    where e::text = in_halal_scope) then
    raise exception 'invalid halal_scope' using errcode = '22023';
  end if;

  -- spatial dedupe: a non-rejected store with the same (case-insensitive) name
  -- within 150 m is treated as the same place.
  select s.id into v_dup
  from public.stores s
  where s.status in ('approved','pending')
    and lower(btrim(s.name)) = lower(btrim(in_name))
    and st_dwithin(s.location, v_point, 150)
  limit 1;
  if v_dup is not null then
    raise exception 'duplicate store nearby: %', v_dup using errcode = '23505';
  end if;

  insert into public.stores
    (name, category, halal_scope, address, city, state, zip, location,
     certifications, source, submitted_by, status)
  values
    (btrim(in_name), in_category::store_category, in_halal_scope::halal_scope,
     coalesce(btrim(in_address), ''), coalesce(btrim(in_city), ''),
     coalesce(btrim(in_state), ''), coalesce(btrim(in_zip), ''),
     v_point, '{}', 'community', v_uid, 'pending')
  returning id into v_id;

  return v_id;
end;
$$;

grant execute on function public.submit_store(
  text, text, text, text, text, text, text, double precision, double precision
) to authenticated;

-- NOTE (approval): pending → approved is a MANUAL/admin action done with the
-- service-role key (or a SQL editor session), which bypasses RLS — same model as
-- review_requests verdicts:
--   update public.stores set status='approved' where id='<uuid>';
-- Approving a store is all it takes for it to appear on the public map.

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0004_rls_hardening.up.sql
-- ─────────────────────────────────────────────────────────────────────────

-- ============================================================================
-- 0004_rls_hardening (UP) — make the Row-Level Security posture EXPLICIT and
-- consolidated in one auditable place. The individual policies already exist
-- (stores from 0001/0003, review_requests from supabase-setup.sql); this migration
-- (re)asserts the complete, canonical set so the whole security surface can be
-- reviewed in a single file, and guarantees RLS is enabled everywhere.
--
-- Posture (the four invariants the test matrix in supabase/tests/rls_matrix.sql
-- proves):
--   1. anon/public may SELECT only APPROVED stores.
--   2. an authenticated user may SELECT their OWN rows (any status) — and only
--      their own; never another user's pending submission.
--   3. there is NO user INSERT/UPDATE/DELETE policy on stores → a user cannot
--      self-approve (change status) or write directly; the ONLY write path is the
--      SECURITY DEFINER submit_store() RPC, which forces status='pending',
--      source='community', submitted_by=auth.uid().
--   4. review_requests: a user may INSERT/SELECT only their OWN rows; there is no
--      user UPDATE policy → a user cannot change a verdict. Verdicts/approvals are
--      service-role/admin only.
--
-- Reversible: see 0004_rls_hardening.down.sql (intentionally FAIL-CLOSED).
-- ============================================================================

-- 1) Force RLS on (idempotent) -----------------------------------------------
alter table public.stores          enable row level security;
alter table public.review_requests enable row level security;

-- 2) stores policies (canonical restatement) ---------------------------------
drop policy if exists "read approved stores" on public.stores;
create policy "read approved stores" on public.stores
  for select
  using (status = 'approved');

drop policy if exists "read own submissions" on public.stores;
create policy "read own submissions" on public.stores
  for select to authenticated
  using (submitted_by = auth.uid());

-- NOTE: deliberately NO insert/update/delete policy on public.stores. Under RLS,
-- the absence of a permissive policy = denied. Writes go only through
-- submit_store(); status changes (approval) require the service-role key.

-- 3) review_requests policies (canonical restatement) ------------------------
drop policy if exists "insert own review" on public.review_requests;
create policy "insert own review" on public.review_requests
  for insert to authenticated
  with check (auth.uid() = user_id);

drop policy if exists "read own reviews" on public.review_requests;
create policy "read own reviews" on public.review_requests
  for select to authenticated
  using (auth.uid() = user_id);

-- NOTE: deliberately NO user UPDATE policy on review_requests → a user cannot set
-- their own verdict. Reviewers write verdicts with the service-role key.

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0005_store_votes.up.sql
-- ─────────────────────────────────────────────────────────────────────────

-- ============================================================================
-- 0005_store_votes (UP) — community confirm/dispute votes on a store.
--   • store_votes: ONE vote per (store, user); re-voting updates it.
--   • vote_store() RPC: the only write path — auth-gated, validates the vote,
--     allows votes only on APPROVED stores, upserts the user's vote, recomputes
--     stores.confirm_count / dispute_count, and returns the fresh counts.
-- Reversible: see 0005_store_votes.down.sql.
-- ============================================================================

create table if not exists public.store_votes (
  id         uuid primary key default gen_random_uuid(),
  store_id   uuid not null references public.stores(id)   on delete cascade,
  user_id    uuid not null references auth.users(id)      on delete cascade,
  vote       text not null check (vote in ('confirm','dispute')),
  created_at timestamptz not null default now(),
  unique (store_id, user_id)
);

create index if not exists store_votes_store_idx on public.store_votes(store_id);

-- RLS: a user may read their OWN votes (so the UI can show their current choice).
-- There is NO insert/update/delete policy — writes go only through vote_store().
alter table public.store_votes enable row level security;
grant select on public.store_votes to authenticated;

drop policy if exists "read own votes" on public.store_votes;
create policy "read own votes" on public.store_votes
  for select to authenticated
  using (user_id = auth.uid());

create or replace function public.vote_store(in_store_id uuid, in_vote text)
returns table (confirm_count int, dispute_count int)
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_c   int;
  v_d   int;
begin
  if v_uid is null then
    raise exception 'auth required' using errcode = '28000';
  end if;
  if in_vote not in ('confirm','dispute') then
    raise exception 'invalid vote' using errcode = '22023';
  end if;
  if not exists (select 1 from public.stores
                 where id = in_store_id and status = 'approved') then
    raise exception 'store not found' using errcode = 'P0002';
  end if;

  insert into public.store_votes (store_id, user_id, vote)
  values (in_store_id, v_uid, in_vote)
  on conflict (store_id, user_id)
  do update set vote = excluded.vote, created_at = now();

  select count(*) filter (where vote = 'confirm'),
         count(*) filter (where vote = 'dispute')
    into v_c, v_d
    from public.store_votes
   where store_id = in_store_id;

  update public.stores
     set confirm_count = v_c, dispute_count = v_d
   where id = in_store_id;

  confirm_count := v_c;
  dispute_count := v_d;
  return next;
end;
$$;

grant execute on function public.vote_store(uuid, text) to authenticated;

-- ─────────────────────────────────────────────────────────────────────────
-- source: supabase/migrations/0006_account_lifecycle.up.sql
-- ─────────────────────────────────────────────────────────────────────────

-- ============================================================================
-- 0006_account_lifecycle (UP) — App Store Guideline 5.1.1(v) account deletion.
--   • apple_tokens: server-side store of each user's Sign in with Apple refresh
--     token (written by the apple-store-token function, read by apple-revoke).
--     Service-role only — RLS denies all client access.
--   • delete_my_account(): the authenticated user erases their own data. Personal
--     rows are deleted; APPROVED community stores are anonymized (submitted_by →
--     null) so the public map survives without keeping a personal link.
-- Reversible: see 0006_account_lifecycle.down.sql.
-- ============================================================================

-- 1) Apple refresh-token store (for token revocation on deletion) -------------
create table if not exists public.apple_tokens (
  user_id       uuid primary key references auth.users(id) on delete cascade,
  refresh_token text not null,
  updated_at    timestamptz not null default now()
);

-- RLS on, NO policies → only the service-role key (server functions) may touch it.
alter table public.apple_tokens enable row level security;

-- 2) The authenticated-user account-deletion RPC -----------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'auth required' using errcode = '28000';
  end if;

  -- Fully personal rows → delete.
  delete from public.store_votes     where user_id = v_uid;
  delete from public.review_requests where user_id = v_uid;

  -- Pending submissions (never made public) → delete.
  delete from public.stores where submitted_by = v_uid and status <> 'approved';
  -- Approved community stores → keep the listing, drop the personal link.
  update public.stores set submitted_by = null
    where submitted_by = v_uid and status = 'approved';
end;
$$;

grant execute on function public.delete_my_account() to authenticated;

-- DELETION ORDER (app → server): the app calls this RPC to erase its public rows
-- FIRST, then calls the apple-revoke function LAST. That function reads the stored
-- Apple refresh token, revokes it with Apple, and admin-deletes auth.users (which
-- cascades apple_tokens). Revoke runs last because deleting auth.users invalidates
-- the session this RPC needs. Review photos in the `review-photos` Storage bucket
-- (under {uid}/…) are removed by the app from its own folder during deletion;
-- Storage objects aren't reachable from SQL here.

